# Actually construct the output based on this understanding
def construct_output(input_grid):
    output = [row[:] for row in input_grid]  # Copy

    markers = [[r, c] for r in range(len(input_grid)) for c in range(len(input_grid[0])) if input_grid[r][c] == 2]

    # For each cell that's 3 and in 3x3 of some marker, turn it into 1
    h, w = len(input_grid), len(input_grid[0])
    for r in range(h):
        for c in range(w):
            if input_grid[r][c] == 3:
                for mr, mc in markers:
                    if mr-1 <= r <= mr+1 and mc-1 <= c <= mc+1:
                        output[r][c] = 1
                        break

    return output

