def find_vertical_chain(marker_pos, grid):
    mr, mc = marker_pos
    chain = [marker_pos]
    # Look up
    r = mr - 1
    while r >= 0 and grid[r][mc] == 2:
        chain.append((r, mc))
        r -= 1
    # Look down  
    r = mr + 1
    while r < 20 and grid[r][mc] == 2:
        chain.append((r, mc))
        r += 1
    return chain

